CREATE FUNCTION internal.initial_requested_provenance_matches(p_received JSONB,p_requested JSONB)
RETURNS BOOLEAN LANGUAGE SQL IMMUTABLE SET search_path='' AS $$
 SELECT (p_received->'version' IS DISTINCT FROM '3'::JSONB AND p_received=p_requested) OR (
  p_received->'version'='3'::JSONB AND p_requested->'version'='3'::JSONB
  AND p_received->>'model'='gemini-3.8-flash' AND p_received->>'returned_model'='gemini-3.8-flash'
  AND p_requested->'returned_model' IN ('null'::JSONB,'"gemini-3.8-flash"'::JSONB)
  AND p_received-'returned_model'=p_requested-'returned_model');
$$;
REVOKE ALL ON FUNCTION internal.initial_requested_provenance_matches(JSONB,JSONB) FROM PUBLIC,anon,authenticated,service_role;

