ALTER TABLE public.scans ADD CONSTRAINT scans_gemini_v3_returned_identity CHECK (
 identification_provenance->'version' IS DISTINCT FROM '3'::JSONB OR
 COALESCE(identification_provenance->>'model'='gemini-3.8-flash' AND identification_provenance->>'returned_model'='gemini-3.8-flash',FALSE));
ALTER TABLE internal.observation_analysis_results ADD CONSTRAINT observation_results_gemini_v3_returned_identity CHECK (
 result_snapshot#>'{identification_provenance,version}' IS DISTINCT FROM '3'::JSONB OR
 COALESCE(result_snapshot#>>'{identification_provenance,model}'='gemini-3.8-flash' AND result_snapshot#>>'{identification_provenance,returned_model}'='gemini-3.8-flash',FALSE));
